bp_d4_short_entry.source_text:
@startuml
state Site {
  state Block {
    state Floor {
      state Room {
        state in1 <<entryPoint>>
        in1 --> Desk
      }
      Corridor --> in1
    }
    Lift --> Corridor
  }
  Gate --> Lift
}
@enduml

bp_d4_wide_exit.source_text:
@startuml
state Site {
  state Block {
    state Floor {
      state Room {
        Desk --> leave
        state "Leaving The Room Now" as leave <<exitPoint>>
      }
      leave --> Corridor
    }
    Corridor --> Lift
  }
  Lift --> Exit
}
@enduml

bp_entry_exit_same_cluster_short.source_text:
@startuml
state Works {
  state Oven {
    state i <<entryPoint>>
    state o <<exitPoint>>
    i --> Bake
    Bake --> o
  }
  Mix --> i
  o --> Pack
}
@enduml

bp_entry_exit_same_cluster_wide.source_text:
@startuml
state Works {
  state Oven {
    state "Raw Dough Arrives" as raw <<entryPoint>>
    state "Baked Loaves Leave" as baked <<exitPoint>>
    raw --> Bake
    Bake --> baked
  }
  Mix --> raw
  baked --> Pack
}
@enduml

bp_multiline_label.source_text:
@startuml
state Yard {
  state Shed {
    Saw --> out1
    state "Outgoing\nTimber\nStack" as out1 <<exitPoint>>
  }
  out1 --> Truck
}
@enduml

bp_root_wide_multiline.source_text:
@startuml
state Shed {
  Saw --> out1
  state "Outgoing\nTimber Stack Here" as out1 <<exitPoint>>
}
out1 --> Truck
@enduml

bp_wide_entry_with_note.source_text:
@startuml
state Works {
  state Oven {
    state "Raw Dough Arrives" as raw <<entryPoint>>
    raw --> Bake
    note right of Bake : warm
  }
  Mix --> raw
  Bake --> Pack
}
@enduml

np_concurrent_regions.source_text:
@startuml
state Plant {
  state Pump {
    state inlet <<entryPoint>>
    inlet --> Valve
    note right of Valve : open
  }
  Valve --> Tank
  --
  Fan --> Duct
  note left of Duct : cold
}
@enduml

np_link_note_in_cluster.source_text:
@startuml
state Mill {
  state Gear {
    state feed <<entryPoint>>
    feed --> Cog
    Cog --> Axle
    note on link : spins
  }
  Axle --> Belt
}
@enduml

np_note_before_target.source_text:
@startuml
