np_root_three_clusters.source_text:
@startuml
state North {
  Pine --> Fir
  note right of Pine : tall
}
state South {
  Palm --> Fern
}
state East {
  Oak --> Elm
  note left of Elm : wide
}
Start --> Pine
Fir --> Palm
Fern --> Oak
Elm --> Stop
@enduml

np_three_notes_one_cluster.source_text:
@startuml
state Dock {
  state Crane {
    state hook <<entryPoint>>
    hook --> Lift
    note right of Lift : one
    note left of Lift : two
    note bottom of Lift : three
  }
  Lift --> Barge
  Barge --> Sea
}
@enduml
